#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <array>
#include <climits>
using namespace std;

const int MAX_N = 300;
const int INF = 1000000000;

struct Edge {
    int dest;
    int rev;
    int flow;
    int cap;
    Edge(int d, int r, int f, int c) : dest(d), rev(r), flow(f), cap(c) {}
};

vector<Edge> g[MAX_N];
int lvl[MAX_N], cur[MAX_N], s, t;

void link(int u, int v, int c, int rc = 0) {
    g[u].emplace_back(v, (int)g[v].size(), 0, c);
    g[v].emplace_back(u, (int)g[u].size() - 1, 0, rc);
}

bool level_graph() {
    fill(lvl, lvl + MAX_N, -1);
    lvl[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty() && lvl[t] == -1) {
        int u = q.front(); q.pop();
        for (const auto& e : g[u]) {
            int v = e.dest;
            if (lvl[v] == -1 && e.flow < e.cap) {
                lvl[v] = lvl[u] + 1;
                q.push(v);
            }
        }
    }
    return lvl[t] != -1;
}

int augment(int u, int f) {
    if (u == t || !f) return f;
    for (int& i = cur[u]; i < (int)g[u].size(); ++i) {
        Edge& e = g[u][i];
        int v = e.dest;
        if (lvl[v] != lvl[u] + 1) continue;
        int pushed = augment(v, min(f, e.cap - e.flow));
        if (pushed) {
            e.flow += pushed;
            g[v][e.rev].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int dinic() {
    int total = 0;
    while (level_graph()) {
        fill(cur, cur + MAX_N, 0);
        int pushed;
        while ((pushed = augment(s, INF))) {
            total += pushed;
        }
    }
    return total;
}

const int dr[4] = {-1, 0, 0, 1};
const int dc[4] = {0, -1, 1, 0};

int N, M;
vector<vector<int>> wall, limit, dist;
vector<string> grid1, grid2;

void bfs(int r, int c, vector<vector<int>>& d, bool use_limit = false) {
    for (int i = 0; i < N; ++i)
        fill(d[i].begin(), d[i].end(), -1);
    d[r][c] = 0;
    queue<array<int, 2>> q;
    q.push({r, c});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (use_limit && d[x][y] == limit[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int nx = x + dr[k], ny = y + dc[k];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N || d[nx][ny] != -1 || wall[nx][ny]) continue;
            if (use_limit && limit[nx][ny] > -1 && d[x][y] + 1 > limit[nx][ny]) continue;
            d[nx][ny] = d[x][y] + 1;
            q.push({nx, ny});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> M;
    grid1.resize(N);
    grid2.resize(N);
    for (auto& s : grid1) cin >> s;
    for (auto& s : grid2) cin >> s;
    wall.assign(N, vector<int>(N));
    limit.assign(N, vector<int>(N));
    dist.assign(N, vector<int>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            wall[i][j] = (grid1[i][j] == 'Y');
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (grid1[i][j] == 'Z')
                bfs(i, j, limit);
    s = 2 * N * N + 5;
    t = s + 1;
    for (int x = 0; x < N; ++x) {
        for (int y = 0; y < N; ++y) {
            if (grid1[x][y] == 'Z' || grid1[x][y] == 'Y') continue;
            link(s, N * x + y, grid1[x][y] - '0');
            link(N * N + N * x + y, t, grid2[x][y] - '0');
            bfs(x, y, dist, true);
            for (int xp = 0; xp < N; ++xp) {
                for (int yp = 0; yp < N; ++yp) {
                    if (dist[xp][yp] != -1 && dist[xp][yp] <= M) {
                        link(N * x + y, N * N + N * xp + yp, INF);
                    }
                }
            }
        }
    }
    cout << dinic() << '\n';
    return 0;
}
